export const GUIDE_NAMES: readonly string[] = GUIDES.map((g) => g.name);

export function getGuide(name: string): Guide | undefined {
  return GUIDES.find((g) => g.name === name);
}

export function getPrompt(name: string): PromptTemplate | undefined {
  return PROMPTS.find((p) => p.name === name);
}

/**
 * Sent to the client in the initialize result, which most clients fold into the
 * system prompt. Always resident, so it stays short and points at `ae_guide`
 * for the rest.
 */
export const SERVER_INSTRUCTIONS = "You are driving a live After Effects session through this server. The user sees\nevery change as it happens and every call is a real undo step in their project.\n\nRead the guidance before you build. `ae_guide({topic: \"after-effects\"})` covers\norienting in a project, keyframes and easing, expressions, effects, text, shapes,\nand the traps that silently produce wrong output. In Claude Code and claude.ai\nthe `after-effects` skill is the same text — load one carrier, not both.\nTopics: ae-setup, after-effects, extendscript-gotchas, style-guide, whats-new.\n\nThree habits that matter before that call returns:\n\n- Identify by `id`, never by `index` — a layer's index shifts on every insert.\n- Bound your reads (`include`, `shapeDetail: \"compact\"`) and treat screenshots as\n  one-off diagnostics rather than a feedback loop. Every tool result is re-sent\n  to you on every later request in the session.\n- If a tool reports it cannot reach After Effects, call `check_setup` and relay\n  its `nextSteps` verbatim; do not diagnose CEP by hand.";
